css:
.d-overflow-tab-scroll{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-overflow-tab-scroll *,.d-overflow-tab-scroll *::before,.d-overflow-tab-scroll *::after{box-sizing:border-box}
.d-overflow-tab-scroll [hidden]{display:none!important}
.d-overflow-tab-scroll .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-overflow-tab-scroll .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-overflow-tab-scroll label{display:block;margin:8px 0}
.d-overflow-tab-scroll input,.d-overflow-tab-scroll select,.d-overflow-tab-scroll textarea,.d-overflow-tab-scroll button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-overflow-tab-scroll input:not([type=checkbox]):not([type=radio]),.d-overflow-tab-scroll select,.d-overflow-tab-scroll textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-overflow-tab-scroll button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-overflow-tab-scroll button:disabled{opacity:.5;cursor:default}
.d-overflow-tab-scroll :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-overflow-tab-scroll [aria-invalid=true]{border-color:var(--warn)!important}
.d-overflow-tab-scroll .d-scroll{max-width:100%;overflow:auto}
.d-overflow-tab-scroll table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-overflow-tab-scroll th,.d-overflow-tab-scroll td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-overflow-tab-scroll caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-overflow-tab-scroll progress{width:100%;accent-color:var(--ink)}
.d-overflow-tab-scroll pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-overflow-tab-scroll h3,.d-overflow-tab-scroll p{margin:8px 0}
.d-overflow-tab-scroll [aria-pressed=true],.d-overflow-tab-scroll [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-overflow-tab-scroll .d-grow{flex:1;min-width:100px}
.d-overflow-tab-scroll summary{cursor:pointer;padding:6px 0}
.d-overflow-tab-scroll ul,.d-overflow-tab-scroll ol{padding-left:24px}
.d-overflow-tab-scroll [data-strip]{display:flex;flex:1;min-width:0;gap:6px;overflow:auto;scrollbar-width:thin}.d-overflow-tab-scroll [data-tab]{flex:0 0 auto}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const strip=q('[data-strip]');const sync=()=>{q('[data-left]').disabled=strip.scrollLeft<=1;q('[data-right]').disabled=strip.scrollLeft+strip.clientWidth>=strip.scrollWidth-1;};q('[data-left]').onclick=()=>strip.scrollBy({left:-160});q('[data-right]').onclick=()=>strip.scrollBy({left:160});strip.onscroll=sync;qa('[data-tab]').forEach(button=>button.onclick=()=>{qa('[data-tab]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));button.scrollIntoView({block:'nearest',inline:'nearest'});say('当前阶段：'+button.textContent);sync();});sync();if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(()=>{if(!root.isConnected)observer.disconnect();else sync();});observer.observe(strip);}})(root, q, qa, say);
}
